# Refined full portfolio previews: project data and additional simulation.
# Run from images/source: Rscript survival-thumbnail-polished.R
# Simulation generated by survival-variants.R: 400 subjects, seed 4214242.
# Its time scale is interpreted as years for this illustrative preview only.
# Project data have no documented time unit.
# Pointwise log-log bands: 80% for project data, 95% for additional simulation.
library(survival)
text_colour <- '#43566a'
for(dataset in c('original','simulated')) {
 input <- if(dataset=='simulated') 'survival-illustrative-data.csv' else 'survival-thumbnail-data.csv'
 d <- read.csv(input,check.names=FALSE)
 expected_n <- if(dataset=='simulated') 400 else 30
 stopifnot(nrow(d)==expected_n,all(table(d$Gruppe)==expected_n/2))
 confidence <- if(dataset=='simulated') 0.95 else 0.80
 fit <- survfit(Surv(Zeit,status=='tot')~Gruppe,data=d,conf.int=confidence,conf.type='log-log')
colours <- c('#147bb5','#e57245')
step_points <- function(t,v) list(x=rep(t,each=2)[-1],y=rep(v,each=2)[-length(rep(v,each=2))])
png(paste0('../previews/survival-', dataset, '-full.png'),width=1200,height=760,
    res=150,pointsize=18,type='cairo',bg='#f5f8fb')
par(mar=c(3.1,3.6,0.7,0.9),mgp=c(1.9,0.45,0),family='sans',
    col.axis=text_colour,col.lab=text_colour,fg='#899baa',font=1,font.axis=1,font.lab=1)
plot.new()
plot.window(xlim=c(0,14),ylim=c(0,1),xaxs='i',yaxs='i')
abline(h=seq(0,1,0.2),v=seq(0,14,2),col='#e3eaf0',lwd=0.8)
for(i in seq_along(fit$strata)) {
 f <- fit[i];valid <- is.finite(f$lower)&is.finite(f$upper)
 lo <- step_points(c(0,f$time[valid]),c(1,f$lower[valid]))
 hi <- step_points(c(0,f$time[valid]),c(1,f$upper[valid]))
 polygon(c(lo$x,rev(hi$x)),c(lo$y,rev(hi$y)),col=adjustcolor(colours[i],alpha.f=0.18),border=NA)
}
lines(fit,col=colours,lwd=4,lty=1,conf.int=FALSE,mark.time=TRUE,pch=3,cex=0.42)
axis(1,at=seq(0,14,2),tck=-0.012,lwd=1.4,lwd.ticks=0.8,cex.axis=0.9)
axis(2,at=seq(0,1,0.2),labels=paste0(seq(0,100,20),'%'),las=1,
     tck=-0.012,lwd=1.4,lwd.ticks=0.8,cex.axis=0.9)
mtext(if(dataset=='simulated') 'Time (years)' else 'Time (unspecified unit)',
      side=1,line=1.8,cex=0.9,col=text_colour,font=1)
mtext('Survival probability',side=2,line=2.6,cex=0.9,col=text_colour,font=1)
legend('topright',inset=c(0.02,0.04),legend=c('Treatment','Control'),col=colours,
       lty=1,lwd=4,bty='n',text.col=text_colour,cex=0.85,seg.len=1.5,y.intersp=1.1)
dev.off()
cat(dataset, ':', nrow(d), 'observations; confidence:', confidence, '\n')
}
